import{_ as l,a0 as r,w as p,s as a,ao as i,I as e,x as s,a1 as n,A as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"简单技巧：从 Ubuntu 桌面上删除主文件夹图标 | LCTT x X-CMD","titleTemplate":false,"description":"简单技巧：从 Ubuntu 桌面上删除主文件夹图标 | LCTT (202309) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"简单技巧：从 Ubuntu 桌面上删除主文件夹图标 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"简单技巧：从 Ubuntu 桌面上删除主文件夹图标 | LCTT (202309) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202309/20230822 Remove Home Folder Icon from Ubuntu Desktop","title":"简单技巧：从 Ubuntu 桌面上删除主文件夹图标","tag":"202309","desc":""},"relativePath":"202309/20230822 Remove Home Folder Icon from Ubuntu Desktop.md","filePath":"[post].md"}'),d={name:"202309/20230822 Remove Home Folder Icon from Ubuntu Desktop.md"};function b(m,t,g,f,k,h){const o=r("Link");return p(),a("div",null,[t[22]||(t[22]=i('<h1 id="简单技巧-从-ubuntu-桌面上删除主文件夹图标" tabindex="-1">简单技巧：从 Ubuntu 桌面上删除主文件夹图标 <a class="header-anchor" href="#简单技巧-从-ubuntu-桌面上删除主文件夹图标" aria-label="Permalink to “简单技巧：从 Ubuntu 桌面上删除主文件夹图标”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202309/02/153353a01ouhl1a5svhym0.jpg" alt=""></p><blockquote><p>对于不想在桌面上看到主文件夹图标的 Ubuntu 用户，这里有一个简单技巧。</p></blockquote><p>Ubuntu 使用定制的 GNOME 版本，由于侧边启动器，它的外观与旧的 Unity 桌面有些相似。</p><p>普通 GNOME 和 Ubuntu 的 GNOME 之间的另一个区别是桌面上主文件夹和回收站的使用。这些图标就在那里，以便你可以快速访问它们。</p><p><img src="https://itsfoss.com/content/images/2023/08/home-folder-icon-on-ubuntu-desktop.png" alt="Home folder icon on Ubuntu desktop"></p><p>如果你觉得不美观，可以从桌面视图中删除主文件夹。</p><p>让我分享一下 GUI 和命令行方法。</p><h3 id="在-ubuntu-中隐藏桌面上的主文件夹图标" tabindex="-1">在 Ubuntu 中隐藏桌面上的主文件夹图标 <a class="header-anchor" href="#在-ubuntu-中隐藏桌面上的主文件夹图标" aria-label="Permalink to “在 Ubuntu 中隐藏桌面上的主文件夹图标”">​</a></h3><p>你只需要这样做：</p>',10)),e("p",null,[e("strong",null,[t[1]||(t[1]=s("在 Ubuntu 中按 ",-1)),t[2]||(t[2]=e("code",null,"Super + D",-1)),t[3]||(t[3]=s()),n(o,{href:"https://itsfoss.com/ubuntu-shortcuts/"},{default:u(()=>[...t[0]||(t[0]=[s("键盘快捷键",-1)])]),_:1}),t[4]||(t[4]=s("访问桌面",-1))]),t[5]||(t[5]=s("。",-1))]),t[23]||(t[23]=i('<p>现在<strong>右键单击桌面上的空白区域</strong>。</p><p>从右键单击上下文菜单中，<strong>选择<ruby>桌面图标设置<rt>Desktop Icons Settings</rt></ruby></strong>。</p><p><img src="https://itsfoss.com/content/images/2023/08/access-ubuntu-desktop-icon-settings.png" alt="Right click on the desktop and click the Desktop Icons Settings"></p><p>它将在“<ruby>设置<rt>Settings</rt></ruby>”应用中打开 <ruby>Ubuntu 桌面<rt>Ubuntu Desktop</rt></ruby>设置选项。你也可以通过打开“设置”应用并转到侧边栏中的“Ubuntu 桌面”选项来访问它。</p><p>在这里，你将看到<strong><ruby>显示个人文件夹<rt>Show Personal folder</rt></ruby>的切换选项</strong>。将其关闭以禁用桌面上的主文件夹图标。</p><p><img src="https://itsfoss.com/content/images/2023/08/disable-home-folder-icon-on-ubuntu-desktop.png" alt="Disable the Show Personal folder button"></p><blockquote><p>💡 想要恢复主文件夹图标吗？ 再次切换它。</p></blockquote><h3 id="使用命令行禁用主文件夹图标" tabindex="-1">使用命令行禁用主文件夹图标 <a class="header-anchor" href="#使用命令行禁用主文件夹图标" aria-label="Permalink to “使用命令行禁用主文件夹图标”">​</a></h3><p>是的，你可以从命令行完全禁用主文件夹图标。</p><p>打开终端并使用以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gsettings set org.gnome.shell.extensions.ding show-home false</span></span></code></pre></div><p>效果将是立竿见影的。</p><p>要恢复图标，请使用相同的命令，但使用 <code>true</code> 而不是 <code>false</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gsettings set org.gnome.shell.extensions.ding show-home true</span></span></code></pre></div><p>看到那有多简单了吗？ 也可以采取类似的步骤来删除回收站图标。</p>',15)),e("blockquote",null,[e("p",null,[e("strong",null,[n(o,{href:"https://itsfoss.com/remove-trash-icon-ubuntu-desktop/"},{default:u(()=>[...t[6]||(t[6]=[s("如何在 Ubuntu 中移走桌面的回收站图标",-1)])]),_:1})])])]),t[24]||(t[24]=e("p",null,[e("em",null,"（题图：MJ/84c2e427-a8b3-40b7-a753-22f020800242）")],-1)),t[25]||(t[25]=e("hr",null,null,-1)),e("p",null,[t[8]||(t[8]=s("via: ",-1)),n(o,{href:"https://itsfoss.com/ubuntu-remove-home-icon/"},{default:u(()=>[...t[7]||(t[7]=[s("https://itsfoss.com/ubuntu-remove-home-icon/",-1)])]),_:1})]),e("p",null,[t[13]||(t[13]=s("作者：",-1)),n(o,{href:"https://itsfoss.com/author/abhishek/"},{default:u(()=>[...t[9]||(t[9]=[s("Abhishek Prakash",-1)])]),_:1}),t[14]||(t[14]=s(" 选题：",-1)),n(o,{href:"https://github.com/lujun9972"},{default:u(()=>[...t[10]||(t[10]=[s("lujun9972",-1)])]),_:1}),t[15]||(t[15]=s(" 译者：",-1)),n(o,{href:"https://github.com/geekpi"},{default:u(()=>[...t[11]||(t[11]=[s("geekpi",-1)])]),_:1}),t[16]||(t[16]=s(" 校对：",-1)),n(o,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:u(()=>[...t[12]||(t[12]=[s("校对者ID",-1)])]),_:1})]),e("p",null,[t[19]||(t[19]=s("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[17]||(t[17]=[s("LCTT",-1)])]),_:1}),t[20]||(t[20]=s(" 原创编译，",-1)),n(o,{href:"https://linux.cn/"},{default:u(()=>[...t[18]||(t[18]=[s("Linux中国",-1)])]),_:1}),t[21]||(t[21]=s(" 荣誉推出",-1))])])}const x=l(d,[["render",b]]);export{C as __pageData,x as default};
